const envelope = $json;
if (!envelope || envelope.type !== 'release.announcement_due' || envelope.version !== 1) {
  throw new Error('Unsupported CrowdRelay event');
}
const data = envelope.data ?? {};
const fan = data.fan ?? {};
const release = data.release ?? {};
if (!fan.email || !release.id || !release.title || !release.release_date || !release.listen_url) {
  throw new Error('Missing release announcement fields');
}
const polish = String(fan.locale || 'pl').toLowerCase().startsWith('pl');
const publicBase = ("https://virya.music" || 'https://virya.music').replace(/\/$/, '');
const siteUrl = release.site_url || `${publicBase}${polish ? '/pl/' : '/'}`;
const releaseTypes = {
  single: { pl: 'singiel', en: 'single' },
  ep: { pl: 'EP-ka', en: 'EP' },
  album: { pl: 'album', en: 'album' }
};
const releaseType = releaseTypes[String(release.release_type || '').toLowerCase()] || { pl: 'release', en: 'release' };
return [{ json: {
  event_id: envelope.id,
  mail: {
    template: 'crowdrelay-new-release',
    to: fan.email,
    variables: {
      display_name: fan.display_name ?? null,
      locale: fan.locale ?? 'pl-PL',
      artist_name: release.artist_name || 'Virya',
      release_title: release.title,
      release_type: release.release_type || 'release',
      release_type_pl: releaseType.pl,
      release_type_en: releaseType.en,
      release_date: release.release_date,
      listen_url: release.listen_url,
      image_url: release.image_url ?? null,
      site_url: siteUrl,
      total_tracks: release.total_tracks ?? null
    },
    idempotency_key: envelope.id
  }
} }];
